:root { color-scheme: dark; font-family: Inter, ui-sans-serif, system-ui, sans-serif; }* { box-sizing: border-box; }body { margin: 0px; min-height: 100vh; color: rgb(236, 244, 238); background: rgb(7, 17, 13); }body::before { content: ""; position: fixed; inset: 0px; pointer-events: none; background: radial-gradient(circle at 80% 0%, rgba(22, 75, 52, 0.3), transparent 38%), linear-gradient(135deg, rgba(255, 255, 255, 0.02), transparent 45%); }main { width: min(980px, 100% - 40px); margin: 0px auto; padding: 52px 0px 80px; position: relative; }header { display: flex; justify-content: space-between; align-items: center; margin-bottom: 54px; }.brand { display: flex; gap: 12px; align-items: center; font-weight: 720; letter-spacing: -0.02em; }.mark { width: 28px; height: 28px; border-radius: 8px; display: grid; place-items: center; color: rgb(7, 17, 13); background: rgb(158, 240, 189); box-shadow: rgba(88, 217, 148, 0.26) 0px 0px 36px; }.pill { border: 1px solid rgba(149, 204, 168, 0.157); border-radius: 999px; padding: 7px 11px; color: rgb(159, 181, 167); font-size: 12px; }.eyebrow { color: rgb(141, 220, 172); font-size: 12px; font-weight: 700; letter-spacing: 0.13em; text-transform: uppercase; }h1 { max-width: 680px; margin: 14px 0px 12px; font-size: clamp(38px, 7vw, 66px); line-height: 0.98; letter-spacing: -0.055em; }.lede { max-width: 600px; color: rgb(147, 169, 156); font-size: 17px; line-height: 1.55; }.case { margin-top: 42px; border: 1px solid rgba(183, 223, 198, 0.125); border-radius: 22px; overflow: hidden; background: rgba(13, 26, 20, 0.85); box-shadow: rgba(0, 0, 0, 0.467) 0px 28px 90px; backdrop-filter: blur(16px); }.case-head { display: flex; justify-content: space-between; gap: 20px; padding: 25px 28px; border-bottom: 1px solid rgba(183, 223, 198, 0.086); }.case-title { font-size: 20px; font-weight: 700; letter-spacing: -0.02em; }.case-sub { margin-top: 6px; color: rgb(128, 152, 138); font-size: 13px; }.status { align-self: flex-start; color: rgb(213, 185, 113); background: rgba(213, 185, 113, 0.08); border: 1px solid rgba(213, 185, 113, 0.2); border-radius: 999px; padding: 7px 10px; font-size: 12px; }.grid { display: grid; grid-template-columns: repeat(3, 1fr); }.datum { padding: 24px 28px 26px; border-right: 1px solid rgba(183, 223, 198, 0.07); }.datum:last-child { border-right: 0px; }.label { color: rgb(113, 136, 123); font-size: 12px; margin-bottom: 9px; }.value { font-size: 17px; font-weight: 650; }.action { display: flex; align-items: center; justify-content: space-between; gap: 24px; padding: 22px 28px; background: rgba(255, 255, 255, 0.01); border-top: 1px solid rgba(183, 223, 198, 0.07); }#message { color: rgb(147, 169, 156); font-size: 13px; }button { border: 0px; border-radius: 12px; padding: 13px 18px; background: rgb(158, 240, 189); color: rgb(7, 17, 13); font-style: inherit; font-variant: inherit; font-stretch: inherit; font-size: inherit; line-height: inherit; font-family: inherit; font-optical-sizing: inherit; font-size-adjust: inherit; font-kerning: inherit; font-feature-settings: inherit; font-variation-settings: inherit; font-language-override: inherit; font-weight: 760; cursor: pointer; box-shadow: rgba(98, 223, 152, 0.19) 0px 8px 26px; }button:hover { background: rgb(182, 247, 205); }button:disabled { opacity: 0.65; cursor: wait; }footer { margin-top: 18px; color: rgb(85, 112, 100); font-size: 12px; }@media (max-width: 680px) {
  main { width: min(100% - 24px, 980px); padding-top: 28px; }
  header { margin-bottom: 36px; }
  .grid { grid-template-columns: 1fr; }
  .datum { border-right: 0px; border-bottom: 1px solid rgba(183, 223, 198, 0.07); }
  .action { align-items: stretch; flex-direction: column; }
  button { width: 100%; }
}
